/* v16.xx, seen on the 4K controller screenshot (2026-10-08): on a TV the 2px line was easy to lose, and on an empty slot, which
   is drawn faded, it came out a dim brown. Thicker, with a brighter ring and a soft glow, and the focused thing always at full
   strength, so player 2 finds it from the couch. */
.padfocus{ outline:3px solid var(--amber) !important; outline-offset:2px; opacity:1 !important;
  box-shadow:0 0 0 6px rgba(255,192,74,.35), 0 0 22px 4px rgba(255,192,74,.45) !important; }

check:
{v:'VER',what:'the controller focus is easy to see: a focused element has a 3px amber outline, a glow, and full strength even when faded',
 run:function(){
   var m=document.createElement('div'), el=document.createElement('div'), bad=[], s;
   try{
     m.className='modal on'; m.id='zqxpadring'; m.style.zIndex='-1';
     el.style.cssText='width:80px;height:40px;opacity:.4'; el.className='padfocus';
     m.appendChild(el); document.body.appendChild(m);
     s=getComputedStyle(el);
     if(!(parseFloat(s.outlineWidth)>=3)) bad.push('the focus outline is '+s.outlineWidth);
     if(!(/rgba\(255, 192, 74/.test(s.boxShadow)&&(s.boxShadow.match(/rgba/g)||[]).length>=2)) bad.push('the focus has no glow ('+s.boxShadow.slice(0,60)+')');
     if(parseFloat(s.opacity)<1) bad.push('a faded element stays faded when focused ('+s.opacity+')');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ document.body.removeChild(m); }catch(_r){} }
   return bad.length?bad.join('; '):null; }},
